Here is the commit message:
drm/xe: Map both mem.kernel_bb_pool and usm.bb_pool
MIME-Version: 1.0
Content-Type: text/plain; charset=UTF-8
Content-Transfer-Encoding: 8bit

For integrated devices we need to map both mem.kernel_bb_pool and
usm.bb_pool to be able to run batches from both pools.

Fixes: a682b6a42d4d ("drm/xe: Support device page faults on integrated platforms")
Tested-by: Brian Welty <brian.welty@intel.com>
Signed-off-by: Matthew Brost <matthew.brost@intel.com>
Reviewed-by: Brian Welty <brian.welty@intel.com>
Link: https://patchwork.freedesktop.org/patch/msgid/20240202033440.2351862-1-matthew.brost@intel.com
(cherry picked from commit 72f86ed3c88933d6fa09b036de93621ea71097a7)
Signed-off-by: Thomas Hellström <thomas.hellstrom@linux.intel.com>

Here is the root cause:
The bug was caused by the lack of proper mapping for the `usm.bb_pool` in the migration preparation process, which prevented the system from running batches from both the `mem.kernel_bb_pool` and `usm.bb_pool` on integrated devices. This oversight meant that the necessary batch base offsets were not being set correctly, leading to potential failures when attempting to execute operations that relied on these pools.

Here is the patch:

 static int all_fw_domain_init(struct xe_gt *gt)
 {
 	int err, i;

 	xe_device_mem_access_get(gt_to_xe(gt));
 	err = xe_force_wake_get(gt_to_fw(gt), XE_FORCEWAKE_ALL);
 	if (err)
 		goto err_hw_fence_irq;

 	xe_gt_mcr_set_implicit_defaults(gt);
 	xe_reg_sr_apply_mmio(&gt->reg_sr, gt);

 	err = xe_gt_clock_init(gt);
 	if (err)
 		goto err_force_wake;

 	xe_mocs_init(gt);
 	err = xe_execlist_init(gt);
 	if (err)
 		goto err_force_wake;

 	err = xe_hw_engines_init(gt);
 	if (err)
 		goto err_force_wake;

 	err = xe_uc_init_post_hwconfig(&gt->uc);
 	if (err)
 		goto err_force_wake;

 	if (!xe_gt_is_media_type(gt)) {
 		/*
 		 * USM has its only SA pool to non-block behind user operations
 		 */
 		if (gt_to_xe(gt)->info.has_usm) {
-			gt->usm.bb_pool = xe_sa_bo_manager_init(gt_to_tile(gt), SZ_1M, 16);
+			struct xe_device *xe = gt_to_xe(gt);
+
+			gt->usm.bb_pool = xe_sa_bo_manager_init(gt_to_tile(gt),
+								IS_DGFX(xe) ? SZ_1M : SZ_512K, 16);
 			if (IS_ERR(gt->usm.bb_pool)) {
 				err = PTR_ERR(gt->usm.bb_pool);
 				goto err_force_wake;
 			}
 		}
 	}

 	if (!xe_gt_is_media_type(gt)) {
 		struct xe_tile *tile = gt_to_tile(gt);

 		tile->migrate = xe_migrate_init(tile);
 		if (IS_ERR(tile->migrate)) {
 			err = PTR_ERR(tile->migrate);
 			goto err_force_wake;
 		}
 	}

 	err = xe_uc_init_hw(&gt->uc);
 	if (err)
 		goto err_force_wake;

 	/* Configure default CCS mode of 1 engine with all resources */
 	if (xe_gt_ccs_mode_enabled(gt)) {
 		gt->ccs_mode = 1;
 		xe_gt_apply_ccs_mode(gt);
 	}

 	if (IS_SRIOV_PF(gt_to_xe(gt)) && !xe_gt_is_media_type(gt))
 		xe_lmtt_init_hw(&gt_to_tile(gt)->sriov.pf.lmtt);

 	err = xe_force_wake_put(gt_to_fw(gt), XE_FORCEWAKE_ALL);
 	XE_WARN_ON(err);
 	xe_device_mem_access_put(gt_to_xe(gt));

 	return 0;

 err_force_wake:
 	xe_force_wake_put(gt_to_fw(gt), XE_FORCEWAKE_ALL);
 err_hw_fence_irq:
 	for (i = 0; i < XE_ENGINE_CLASS_MAX; ++i)
 		xe_hw_fence_irq_finish(&gt->fence_irq[i]);
 	xe_device_mem_access_put(gt_to_xe(gt));

 	return err;
 }



